from pathlib import Path
import hashlib, json, sys, time

root = Path(sys.argv[1] if len(sys.argv) > 1 else ".").resolve()
records = []
for p in sorted(root.rglob("*")):
    if not p.is_file():
        continue
    if p.name in {"sha256-manifest.json", "sha256-manifest.txt"}:
        continue
    h = hashlib.sha256()
    with p.open("rb") as f:
        for chunk in iter(lambda: f.read(1024 * 1024), b""):
            h.update(chunk)
    records.append({
        "path": p.relative_to(root).as_posix(),
        "bytes": p.stat().st_size,
        "sha256": h.hexdigest(),
    })
manifest = {
    "generatedAtEpoch": int(time.time()),
    "root": str(root),
    "files": records,
}
(root / "sha256-manifest.json").write_text(
    json.dumps(manifest, ensure_ascii=False, indent=2), encoding="utf-8"
)
(root / "sha256-manifest.txt").write_text(
    "\n".join(f"{r['sha256']}  {r['path']}" for r in records) + "\n", encoding="utf-8"
)
print(f"Hashed {len(records)} files")
